#!/usr/bin/env node

process.noDeprecation = true;

const fs = require('fs');
const path = require('path');
const childProcess = require('child_process');

const {
  assertSupportedNodeVersion,
} = require('../scripts/verify-node-version.cjs');

try {
  assertSupportedNodeVersion(process.versions.node);
} catch (error) {
  process.stderr.write(
    `\n${error.message}\nNode.js runtime: ${process.execPath}\n\n`,
  );
  process.exit(1);
}

const packageRoot = path.resolve(__dirname, '..');
let packageMetadata = null;
try {
  packageMetadata = JSON.parse(
    fs.readFileSync(path.join(packageRoot, 'package.json'), 'utf8'),
  );
} catch {
  packageMetadata = null;
}

if (!process.env.NODE_ENV) {
  try {
    const {
      resolveDefaultNodeEnv,
    } = require('../dist/cli/resolveDefaultNodeEnv.js');
    process.env.NODE_ENV = resolveDefaultNodeEnv(
      packageRoot,
      packageMetadata?.name,
    );
  } catch {
    process.env.NODE_ENV = 'development';
  }
}

process.on('uncaughtException', (error) => {
  console.error('Uncaught exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

const providedArgs = process.argv.slice(2);
const args = providedArgs.length === 0 ? ['open'] : providedArgs;

const runCli = () => {
  let controlPlane = null;
  let commandArgs = args;
  try {
    const {
      isCliControlCommand,
      normalizeCliInvocation,
    } = require('../dist/cli/commandNames.js');
    commandArgs = normalizeCliInvocation(args);
    if (isCliControlCommand(commandArgs[0])) {
      controlPlane = require('../dist/cli/entry.js');
    }
  } catch {
    controlPlane = null;
  }

  if (controlPlane) {
    if (args[0] !== '__hub') {
      process.on('SIGINT', () => {
        if (['context', 'mcp'].includes(commandArgs[0])) {
          const {
            hasActiveGuidanceVerifications,
          } = require('../dist/services/GuidanceVerifierRunner.js');
          if (hasActiveGuidanceVerifications()) return;
        }
        process.exit(0);
      });
    }
    controlPlane.runControlPlane(commandArgs).catch((error) => {
      console.error('CLI error:', error);
      process.exit(1);
    });
    return;
  }

  process.on('SIGINT', () => {
    console.log('\n👋 Goodbye!');
    process.exit(0);
  });

  const { main } = require('../dist/index.js');

  main().catch((error) => {
    console.error('CLI error:', error);
    process.exit(1);
  });
};

const runUpdatedCli = (update) =>
  new Promise((resolve, reject) => {
    const child = childProcess.spawn(
      process.execPath,
      [update.binPath, ...args],
      {
        env: {
          ...process.env,
          RIVET_AUTO_UPDATE_REEXEC: '1',
          RIVET_AUTO_UPDATE_REFRESH: update.refreshIntegrations ? '1' : '0',
        },
        stdio: 'inherit',
      },
    );
    const forwardSignal = (signal) => {
      if (!child.killed) child.kill(signal);
    };
    const forwardSigint = () => forwardSignal('SIGINT');
    const forwardSigterm = () => forwardSignal('SIGTERM');
    const cleanup = () => {
      process.removeListener('SIGINT', forwardSigint);
      process.removeListener('SIGTERM', forwardSigterm);
    };
    process.once('SIGINT', forwardSigint);
    process.once('SIGTERM', forwardSigterm);
    child.once('error', (error) => {
      cleanup();
      reject(error);
    });
    child.once('exit', (code) => {
      cleanup();
      resolve(code ?? 1);
    });
  });

const refreshUpdatedIntegrations = () => {
  const isRefreshRequested = process.env.RIVET_AUTO_UPDATE_REFRESH === '1';
  delete process.env.RIVET_AUTO_UPDATE_REEXEC;
  delete process.env.RIVET_AUTO_UPDATE_REFRESH;
  if (!isRefreshRequested) return { failed: false, refreshed: false };
  try {
    const { redirectLogsToStderr } = require('../dist/utils/logger.js');
    redirectLogsToStderr();
    const { updateHarnesses } = require('../dist/install/harnesses.js');
    const result = updateHarnesses({ isQuiet: true });
    if (!result.isSuccessful) {
      process.stderr.write(
        `Rivet updated, but ${
          result.detectedInstalledCount - result.refreshedCount
        } agent integration(s) could not be refreshed. Run: rivet update\n`,
      );
    }
    return {
      failed: !result.isSuccessful,
      refreshed: result.refreshedCount > 0,
    };
  } catch (error) {
    process.stderr.write(
      `Rivet updated, but its agent integrations could not be refreshed: ${
        error instanceof Error ? error.message : String(error)
      }\n`,
    );
    return { failed: true, refreshed: false };
  }
};

const stopForActiveUpdate = (update) => {
  process.exitCode = 1;
  if (args[0] === 'update') {
    const envelope = {
      schemaVersion: 1,
      ok: false,
      command: 'update',
      error: {
        code: 'OPERATION_FAILED',
        message: update.message,
        details: { updateFailure: update.failure },
      },
    };
    process.stdout.write(`${JSON.stringify(envelope)}\n`);
  }
};

const start = async () => {
  const { getPluginName } = require('../dist/hosts/pluginContext.js');
  if (getPluginName()) {
    const isMaintenanceCommand =
      ['install', 'uninstall', 'update'].includes(args[0]) ||
      (args[0] === 'mcp' && !args.includes('serve'));
    if (isMaintenanceCommand) {
      const { errorResult } = require('../dist/cli/envelope.js');
      const result = errorResult(
        args[0],
        'USAGE_ERROR',
        'Manage this Rivet plugin through its marketplace. Run installation commands outside the plugin runtime to manage a separate CLI installation.',
      );
      process.exitCode = result.exitCode;
      process.stdout.write(`${JSON.stringify(result.envelope)}\n`);
      return;
    }
    runCli();
    return;
  }
  if (args[0] === 'install') {
    runCli();
    return;
  }
  if (process.env.RIVET_AUTO_UPDATE_REEXEC === '1') {
    if (args[0] === 'update') {
      delete process.env.RIVET_AUTO_UPDATE_REEXEC;
      delete process.env.RIVET_AUTO_UPDATE_REFRESH;
      process.env.RIVET_UPDATE_PACKAGE_UPDATED = '1';
    } else {
      refreshUpdatedIntegrations();
    }
    runCli();
    return;
  }

  try {
    const {
      checkAndInstallCliUpdate,
    } = require('../dist/install/automaticCliUpdate.js');
    const update = await checkAndInstallCliUpdate({
      args,
      binPath: path.join(packageRoot, 'bin', 'rivet.js'),
      currentVersion: packageMetadata?.version ?? '0.0.0',
      packageRoot,
    });
    if (update.warning) {
      process.stderr.write(update.warning);
    }
    if (args[0] === 'update' && update.failure) {
      process.env.RIVET_UPDATE_FAILURE = JSON.stringify(update.failure);
    }
    if (args[0] === 'update' && update.checkedVersion) {
      process.env.RIVET_UPDATE_CHECKED_VERSION = update.checkedVersion;
    }
    if (update.action === 'blocked') {
      stopForActiveUpdate(update);
      return;
    }
    if (update.action === 'restart') {
      process.stderr.write(
        `Rivet updated from v${update.previousVersion} to v${update.installedVersion}; continuing with the latest version.\n`,
      );
      try {
        process.exit(await runUpdatedCli(update));
      } catch (error) {
        process.stderr.write(
          `Rivet could not start the updated CLI; continuing in the current process. ${
            error instanceof Error ? error.message : String(error)
          }\n`,
        );
      }
    }
  } catch (error) {
    process.stderr.write(
      `Rivet could not check for updates; continuing with v${
        packageMetadata?.version ?? 'unknown'
      }. ${error instanceof Error ? error.message : String(error)}\n` +
        'Run: npm install -g rivet-design@latest\n',
    );
  }
  runCli();
};

start().catch((error) => {
  console.error('CLI startup error:', error);
  process.exit(1);
});
